private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    if (str == null && prefix == null) {
        return true;
    }
    if (str == null || prefix == null) {
        return false;
    }
    int prefixLen = prefix.length();
    if (prefixLen > str.length()) {
        return false;
    }
    for (int i = 0; i < prefixLen; i++) {
        char cStr = str.charAt(i);
        char cPre = prefix.charAt(i);
        if (cStr == cPre) {
            continue;
        }
        if (ignoreCase) {
            if (Character.toLowerCase(cStr) == Character.toLowerCase(cPre)) {
                continue;
            }
        }
        return false;
    }
    return true;
}

