public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file");
    }
    if (!file.exists()) {
        throw new IOException("File does not exist: " + file);
    }
    java.util.Deque<File> stack = new java.util.ArrayDeque<>();
    java.util.List<File> dirsToDelete = new java.util.ArrayList<>();
    stack.push(file);
    while (!stack.isEmpty()) {
        File f = stack.pop();
        if (f.isDirectory()) {
            File[] children = f.listFiles();
            if (children == null) {
                throw new IOException("Could not list directory: " + f);
            }
            for (File child : children) {
                stack.push(child);
            }
            dirsToDelete.add(f);
        } else {
            f.deleteOnExit();
        }
    }
    for (File d : dirsToDelete) {
        d.deleteOnExit();
    }
}

