private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null || start == null || stop == null) {
        throw new NullPointerException("predicate, start, and stop must not be null");
    }

    /* Return immediately if the starting node satisfies the predicate. */
    if (predicate.test(start)) {
        return new OuterFaceCirculator(start, dir);
    }

    Node current = start;
    /* Traverse the outer face until we either find a node that satisfies the predicate
       or we reach the stop node. */
    while (!current.equals(stop)) {
        /* Move to the next node along the outer face in the specified direction.
           The methods are assumed to exist on the Node class.  */
        current = (dir == 0) ? current.nextOnOuterFace() : current.prevOnOuterFace();

        /* If we looped back to the stop node, terminate the search. */
        if (current.equals(stop)) {
            break;
        }

        /* If the current node satisfies the predicate, stop searching. */
        if (predicate.test(current)) {
            break;
        }
    }

    /* Return a circulator positioned at the node found (or at the stop node). */
    return new OuterFaceCirculator(current, dir);
}

