protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if(tour == null || graph == null){
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    int size = tour.size();
    if(size == 0){
        return null;
    }
    // Convert to list for iteration
    List<E> edgeList = new ArrayList<>(tour);
    List<E> orderedEdges = new ArrayList<>(size);
    List<V> vertexList = new ArrayList<>(size + 1);
    Set<E> used = new HashSet<>(size);
    // Pick arbitrary starting edge
    E startEdge = edgeList.get(0);
    V startVertex = graph.getEdgeSource(startEdge);
    V currentVertex = startVertex;
    vertexList.add(startVertex);
    used.add(startEdge);
    orderedEdges.add(startEdge);
    // Find the other vertex of startEdge
    V nextVertex = graph.getEdgeTarget(startEdge);
    if (nextVertex.equals(startVertex)) {
        // self-loop, just add and finish
        vertexList.add(nextVertex);
        return new GraphPath<>(graph, startVertex, nextVertex, orderedEdges, vertexList);
    }
    currentVertex = nextVertex;
    vertexList.add(currentVertex);
    int usedCount = 1;
    while(usedCount < size){
        boolean found = false;
        for(E e : edgeList){
            if(used.contains(e)){
                continue;
            }
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if(src.equals(currentVertex) || tgt.equals(currentVertex)){
                // Edge connects to current vertex
                orderedEdges.add(e);
                used.add(e);
                usedCount++;
                // Determine next vertex
                V newVertex = src.equals(currentVertex) ? tgt : src;
                currentVertex = newVertex;
                vertexList.add(currentVertex);
                found = true;
                break;
            }
        }
        if(!found){
            // Cannot form a continuous tour
            throw new IllegalArgumentException("Edges cannot form a continuous tour");
        }
    }
    // After using all edges, currentVertex should be startVertex for a closed tour
    if(!currentVertex.equals(startVertex)){
        // If it's not closed, still create path but end at currentVertex
        return new GraphPath<>(graph, startVertex, currentVertex, orderedEdges, vertexList);
    }
    // For a proper cycle include start vertex at end
    vertexList.add(startVertex);
    return new GraphPath<>(graph, startVertex, startVertex, orderedEdges, vertexList);
}

