private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null) {
        return;
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        return;
    }
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return;
    }

    // Ensure bucket with label 0 exists
    if (bucketsByLabel.isEmpty()) {
        return;
    }
    Set<Integer> dest = bucketsByLabel.get(0);
    if (dest == null) {
        dest = new HashSet<>();
        bucketsByLabel.set(0, dest);
    }

    // Move vertices from source to destination and update labels
    for (Integer v : new HashSet<>(source)) {
        dest.add(v);
        if (v >= 0 && v < labels.size()) {
            labels.set(v, 0);
        }
    }

    // Clear the source bucket
    source.clear();
}

