private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null){
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int size = bounds.size();
    List<Integer> suffix = new ArrayList<>(size);
    // initialize list with zeros to allow set
    for (int i = 0; i < size; i++) {
        suffix.add(0);
    }
    long runningSum = 0L;
    for (int i = size - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        long toAdd = (val == null) ? 0L : val.longValue();
        runningSum += toAdd;
        // cast back to Integer; if overflow occurs it wraps, but this matches typical behavior
        suffix.set(i, (int) runningSum);
    }
    return new Pair<>(suffix, runningSum);
}

