public static int nextPrime(int desiredCapacity) {
    // Handle trivial cases
    if (desiredCapacity <= 2) {
        return 2;
    }

    // Start with the desired capacity, making it odd if necessary
    int candidate = desiredCapacity;
    if ((candidate & 1) == 0) {
        candidate++; // ensure odd candidate (since even >2 cannot be prime)
    }

    // Search for the next prime
    while (true) {
        // Quick check: if candidate is divisible by 2, skip (it shouldn't happen due to odd enforcement)
        int limit = (int) Math.sqrt(candidate);
        boolean isPrime = true;
        for (int i = 3; i <= limit; i += 2) { // test only odd divisors
            if (candidate % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate += 2; // move to next odd number
    }
}

