    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    // Serialize the message to a byte array using the provided schema
    byte[] data;
    try {
        // Attempt to use a schema method that serializes to a byte array
        data = schema.toByteArray(message);
    } catch (NoSuchMethodError | UnsupportedOperationException e) {
        // Fallback to using the linked buffer if available
        if (buffer == null) {
            throw new IOException("Unable to serialize message and no buffer provided");
        }
        buffer.clear();
        // Assume the schema has a writeTo method that writes to a LinkedBuffer
        schema.writeTo(message, buffer);
        data = buffer.toByteArray();
